import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1 + n]))
    k = int(data[1 + n]) if len(data) > 1 + n else 0

    if n == 0:
        print()
        return

    k %= n
    if k:
        rotated = arr[-k:] + arr[:-k]
    else:
        rotated = arr

    print(' '.join(map(str, rotated)))

if __name__ == '__main__':
    main()
